/// The gap an extra occupies inside a node with no named child to own it,
/// by (kind id, anonymous tokens before the extra): the model slot whose
/// position the gap holds. `None` when the model has no slot there.
pub fn inner_gap_key(kind: KindId, preceding_tokens: u16) -> Option<&'static str> {
    match (kind.0, preceding_tokens) {
        (176, 0) => Some("statements"),
        (195, 1) => Some("declarations"),
        (199, 1) => Some("elements"),
        (201, 1) => Some("elements"),
        (203, 1) => Some("attributes"),
        (227, 1) => Some("use_clauses"),
        (230, 1) => Some("elements"),
        (249, 2) => Some("bounds"),
        (277, 1) => Some("elements"),
        (283, 1) => Some("initializers"),
        (293, 1) => Some("match_block_arms"),
        (302, 1) => Some("parameters"),
        (313, 1) => Some("statements"),
        (316, 1) => Some("elements"),
        (317, 1) => Some("patterns"),
        (367, 1) => Some("attributes"),
        (405, 1) => Some("token_patterns"),
        (406, 1) => Some("token_patterns"),
        (407, 1) => Some("token_patterns"),
        (408, 1) => Some("tokens"),
        (409, 1) => Some("tokens"),
        (410, 1) => Some("tokens"),
        (411, 1) => Some("delim_tokens"),
        (412, 1) => Some("delim_tokens"),
        (413, 1) => Some("delim_tokens"),
        _ => None,
    }
}
